    // delta: vales aumentam componentes, picos diminuem
    const events = new Map();

    for (let i = 1; i <= m; i++) {
        const left = B[i - 1];
        const right = B[i + 1];
        const curr = B[i];

        let change = 0;
        if (curr < left && curr < right) {
            change = 1; // vale
        } else if (curr > left && curr > right) {
            change = -1; // pico
        }

        if (change !== 0) {
            events.set(curr, (events.get(curr) || 0) + change);
        }
    }

    // Ordenar as alturas distintas com eventos
    const heights = Array.from(events.keys()).sort((a, b) => a - b);

    let comp = 1;
    let maxComp = 1;

    for (let i = 0; i < heights.length; i++) {
        comp += events.get(heights[i]);
        if (comp > maxComp) {
            maxComp = comp;
        }
    }

    console.log(maxComp + 1);
}

